<style>
.s606-product-page{padding:0 0 56px;background:#faf9f6;color:#222925}.s606-product-wrap{width:min(1240px,calc(100% - 48px));margin:auto}.s606-product-breadcrumb{display:flex;flex-wrap:wrap;gap:10px;padding:24px 0;font-size:12px;line-height:1.6;color:#6b706a}.s606-product-breadcrumb a{color:inherit;text-decoration:none}.s606-product-breadcrumb a:hover{color:#244b40}.s606-product-layout{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:56px;align-items:start}.s606-product-gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;min-width:0}.s606-product-gallery img{display:block;width:100%;object-fit:contain;background:#f0eee9;border-radius:6px}.s606-product-gallery img:first-child{grid-column:1/-1;aspect-ratio:1/1;max-height:580px}.s606-product-info{padding:24px 0;min-width:0}.s606-product-info h1{font-size:clamp(28px,3vw,38px);line-height:1.3;font-weight:600;letter-spacing:-.5px;margin:0 0 20px}.s606-product-price{display:block;color:#244b40;font-size:28px;font-weight:700;padding-bottom:24px;border-bottom:1px solid #dfdfd7}.s606-product-summary{font-size:15px;line-height:1.8;color:#62685f;margin:24px 0 28px}.s606-product-purchase label{display:block;font-size:13px;font-weight:600;margin-bottom:10px}.s606-product-purchase>div{display:flex;gap:12px}.s606-product-purchase input{width:84px;min-width:0;min-height:50px;border:1px solid #c8cec4;border-radius:4px;background:#fff;text-align:center;color:#222925;font:inherit}.s606-product-purchase button{flex:1;display:flex;align-items:center;justify-content:space-between;gap:14px;min-height:50px;border:0;border-radius:4px;padding:14px 22px;background:#244b40;color:#fff;font:inherit;font-size:14px;font-weight:600;cursor:pointer}.s606-product-purchase button:hover{background:#193b31}.s606-product-consult{display:flex;justify-content:space-between;gap:12px;margin-top:16px;padding:15px 0;color:#344c41;text-decoration:none;font-size:14px;border-bottom:1px solid #dfdfd7}.s606-product-page :focus-visible{outline:3px solid #879b88;outline-offset:3px}.s606-product-description{margin-top:40px;padding:30px 32px;background:#fff;border:1px solid #e3e4dc;border-radius:6px}.s606-product-description>h2{font-size:24px;font-weight:600;margin:0 0 24px;padding-bottom:18px;border-bottom:1px solid #e3e4dc}.s606-product-prose{max-width:920px;font-size:15px;line-height:1.85;color:#555e54;overflow-wrap:anywhere}.s606-product-prose h2{font-size:22px;line-height:1.4;margin:24px 0 12px;color:#29382e}.s606-product-prose h3{font-size:19px}.s606-product-prose img,.s606-product-prose iframe{max-width:100%;height:auto}.s606-product-prose table{display:block;max-width:100%;overflow:auto}
@media(max-width:850px){.s606-product-layout{gap:28px}.s606-product-info{padding:8px 0}.s606-product-info h1{font-size:28px}}@media(max-width:650px){.s606-product-wrap{width:calc(100% - 32px)}.s606-product-layout{grid-template-columns:1fr;gap:24px}.s606-product-breadcrumb{padding:18px 0}.s606-product-info{padding:0}.s606-product-description{margin-top:28px;padding:22px 20px}.s606-product-purchase button{padding:12px 16px}.s606-product-price{font-size:26px}}
</style>
